/* Morumik photo rig. One approved texture, continuous limb mesh, original bead eyes.
 * No pose swaps: color, yarn pattern and proportions are shared by every reaction.
 * Existing #char classes remain the public state API. */
(function () {
  'use strict';
  const script = document.currentScript;
  /* 캐릭터 사진 3장을 이 파일 안에 넣었습니다 — assets 폴더 없이 동작합니다 */
  const PACK = {'reference.webp':'data:image/webp;base64,','silhouette.webp':'data:image/webp;base64,','eye-underlay.webp':'data:image/webp;base64,'};
  const W=1024, H=1536;
  const EYES=[{x:420,y:620,rx:36,ry:39},{x:643,y:620,rx:35,ry:39}];
  const blinkDelay=()=>18000+Math.random()*10000;
  let assetPromise;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const smooth=(a,b,x)=>{const t=clamp((x-a)/(b-a),0,1);return t*t*(3-2*t);};
  const load=name=>new Promise((resolve,reject)=>{
    const im=new Image(); im.onload=()=>resolve(im); im.onerror=()=>reject(new Error('Character asset: '+name));
    if(!PACK[name]){reject(new Error('Character asset: '+name));return;}
    im.src=PACK[name];
  });
  function surface(w=W,h=H){const c=document.createElement('canvas');c.width=w;c.height=h;return c;}
  function assets(){
    if(!assetPromise) assetPromise=Promise.all([load('reference.webp'),load('silhouette.webp'),load('eye-underlay.webp')]).then(([photo,alpha,underlay])=>{
      const original=surface(),ctx=original.getContext('2d',{willReadFrequently:true});
      ctx.drawImage(photo,0,0,W,H);
      const colors=ctx.getImageData(0,0,W,H);
      const mask=surface(),mc=mask.getContext('2d',{willReadFrequently:true});mc.drawImage(alpha,0,0,W,H);
      const edge=mc.getImageData(0,0,W,H).data;
      // Remove the reference's neutral preview matte only at the transparent fringe.
      // Opaque foreground colors come directly from the supplied photograph.
      for(let i=0;i<colors.data.length;i+=4){
        const a=edge[i+3]/255;
        if(a>0 && a<.98){for(let c=0;c<3;c++)colors.data[i+c]=clamp((colors.data[i+c]-229*(1-a))/a,0,255);}
        colors.data[i+3]=edge[i+3];
      }
      ctx.putImageData(colors,0,0);
      const body=surface(),bc=body.getContext('2d');bc.drawImage(original,0,0);
      for(const e of EYES){
        // Only the small area hidden by the eye changes; glasses and face stay original.
        bc.save();bc.beginPath();bc.ellipse(e.x,e.y,e.rx+2,e.ry+2,0,0,Math.PI*2);bc.clip();
        bc.drawImage(underlay,0,0,W,H);bc.restore();
      }
      const eyes=EYES.map(e=>{
        const eye=surface(2*(e.rx+2),2*(e.ry+2)),ec=eye.getContext('2d');
        ec.beginPath();ec.ellipse(e.rx+2,e.ry+2,e.rx+1,e.ry+1,0,0,Math.PI*2);ec.clip();
        ec.drawImage(original,-e.x+e.rx+2,-e.y+e.ry+2);return eye;
      });
      return {body,eyes};
    }).catch(error=>{assetPromise=null;throw error;});
    return assetPromise;
  }
  function mesh(canvas,texture){
    const gl=canvas.getContext('webgl',{alpha:true,premultipliedAlpha:true,antialias:true});
    if(!gl){const c=canvas.getContext('2d');return {draw(){c.clearRect(0,0,canvas.width,canvas.height);c.drawImage(texture,0,0,canvas.width,canvas.height);},destroy(){}};}
    const shader=(type,source)=>{const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;};
    const vertex=shader(gl.VERTEX_SHADER,`
      attribute vec2 p; attribute vec4 weights;
      uniform vec4 angles; varying vec2 uv;
      vec2 rotateAt(vec2 point, vec2 pivot, float a){vec2 q=point-pivot;float c=cos(a),s=sin(a);return pivot+vec2(c*q.x-s*q.y,s*q.x+c*q.y);}
      void main(){uv=p/vec2(1024.,1536.);vec2 q=p;
        q+=(rotateAt(p,vec2(320.,900.),angles.x)-p)*weights.x;
        q+=(rotateAt(p,vec2(746.,900.),angles.y)-p)*weights.y;
        q+=(rotateAt(p,vec2(392.,1190.),angles.z)-p)*weights.z;
        q+=(rotateAt(p,vec2(664.,1190.),angles.w)-p)*weights.w;
        gl_Position=vec4(q.x/512.-1.,1.-q.y/768.,0.,1.);
      }`);
    const fragment=shader(gl.FRAGMENT_SHADER,`precision mediump float;uniform sampler2D image;varying vec2 uv;void main(){gl_FragColor=texture2D(image,uv);}`);
    const program=gl.createProgram();gl.attachShader(program,vertex);gl.attachShader(program,fragment);gl.linkProgram(program);
    if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(program));gl.useProgram(program);
    const cols=40,rows=60,verts=[],indices=[];
    for(let y=0;y<=rows;y++)for(let x=0;x<=cols;x++){
      const px=x*W/cols,py=y*H/rows;
      // Broad overlapping weights preserve a continuous shoulder instead of cut-out seams.
      const armBand=smooth(810,930,py)*(1-smooth(1130,1220,py));
      const left=armBand*(1-smooth(275,420,px));
      const right=armBand*smooth(650,800,px);
      const leg=smooth(1180,1330,py);
      verts.push(px,py,left,right,leg*(1-smooth(480,545,px)),leg*smooth(510,570,px));
    }
    for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const a=y*(cols+1)+x,b=a+1,c=a+cols+1,d=c+1;indices.push(a,c,b,b,c,d);}
    const vb=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,vb);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(verts),gl.STATIC_DRAW);
    for(const [name,size,offset] of [['p',2,0],['weights',4,8]]){const loc=gl.getAttribLocation(program,name);gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,size,gl.FLOAT,false,24,offset);}
    const ib=gl.createBuffer();gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,ib);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,new Uint16Array(indices),gl.STATIC_DRAW);
    const tex=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,tex);gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL,true);
    gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,texture);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
    const angles=gl.getUniformLocation(program,'angles');gl.clearColor(0,0,0,0);
    return {
      draw(a){gl.viewport(0,0,canvas.width,canvas.height);gl.clear(gl.COLOR_BUFFER_BIT);gl.uniform4fv(angles,a);gl.drawElements(gl.TRIANGLES,indices.length,gl.UNSIGNED_SHORT,0);},
      destroy(){gl.deleteTexture(tex);gl.deleteBuffer(vb);gl.deleteBuffer(ib);gl.deleteProgram(program);gl.deleteShader(vertex);gl.deleteShader(fragment);gl.getExtension('WEBGL_lose_context')?.loseContext();}
    };
  }
  function mount(host){
    host._njCharacter?.destroy();
    const wrap=document.createElement('div');wrap.className='inner rig photo-rig loading';
    wrap.setAttribute('role','img');wrap.setAttribute('aria-label','모루 · 파스텔 털실과 꽃 안경을 쓴 인형');
    const fallback=new Image();fallback.src=PACK['reference.webp'];fallback.alt='';fallback.className='nj-character-static';wrap.appendChild(fallback);
    const body=surface(),face=surface();body.setAttribute('aria-hidden','true');face.setAttribute('aria-hidden','true');face.className='character-face';
    wrap.append(body,face);host.appendChild(wrap);
    const ctx=face.getContext('2d'),motion=matchMedia('(prefers-reduced-motion: reduce)');
    let renderer,data,dead=false,visible=true,frame=0,last=0,stateStart=performance.now(),stateKey='',nextBlink=performance.now()+blinkDelay(),blinkStart=-Infinity;
    let angles=[0,0,0,0];
    const has=(...names)=>names.some(n=>host.classList.contains(n));
    function dimensions(){const rect=wrap.getBoundingClientRect();const width=Math.round(clamp(rect.width*(window.devicePixelRatio||1),256,768));body.width=face.width=width;body.height=face.height=Math.round(width*H/W);}
    const resize=new ResizeObserver(()=>{dimensions();schedule();});resize.observe(wrap);
    function render(now){
      frame=0;if(dead||!data||!renderer)return;
      if(document.hidden||!visible)return;
      if(!motion.matches && now-last<1000/30){schedule();return;}last=now;
      const t=(now-stateStart)/1000,reduced=motion.matches;
      const wave=has('pose-wave','rx-wave','rx-hello','rx-bye');
      const cheer=has('happy','pose-show','rx-cheer','rx-hop','rx-hop2','rx-laugh','rx-tickle','rx-heart','rx-giggle');
      const think=has('thinking','pose-shrug','rx-curious');
      const talk=has('talking'),present=has('pose-present'),point=has('pose-point');
      const hug=has('rx-hug'),stretch=has('rx-stretch');
      let target=[0,0,0,0];
      if(!reduced){
        target=[Math.sin(t*1.5)*.015,-Math.sin(t*1.4)*.015,0,0];
        if(talk||present)target=[.08+Math.sin(t*5)*.035,-.08-Math.sin(t*5+.8)*.035,0,0];
        if(think)target=[.02,-.13+Math.sin(t*3)*.02,0,0];
        if(cheer)target=[.36+Math.sin(t*9)*.04,-.36-Math.sin(t*9)*.04,Math.sin(t*5)*.025,-Math.sin(t*5)*.025];
        if(hug)target=[-.12,.12,0,0];
        if(stretch)target=[.4,-.4,0,0];
        if(point)target[0]=.55+Math.sin(t*3)*.025;
        if(wave)target[0]=.50+Math.sin(t*11)*.12;
        if(has('rx-tapfoot','rx-hop','rx-hop2')){target[2]=Math.sin(t*10)*.06;target[3]=-Math.sin(t*10)*.04;}
      }
      angles=target.map((a,i)=>reduced?a:angles[i]+(a-angles[i])*.22);
      renderer.draw(angles);
      ctx.setTransform(face.width/W,0,0,face.height/H,0,0);ctx.clearRect(0,0,W,H);
      // Reactions move the body, not the approved face. Only a rare idle blink
      // briefly closes the original eyes; sleepy hours never shrink them.
      const reacting=talk||think||has('happy')||Array.from(host.classList).some(n=>n.startsWith('rx-')||n.startsWith('pose-'));
      if(reduced||reacting)blinkStart=-Infinity;
      if(!reduced&&now>=nextBlink){
        if(!reacting)blinkStart=now;
        nextBlink=now+blinkDelay();
      }
      const blinkTime=now-blinkStart;
      const lid=blinkTime>=0&&blinkTime<140?1-.94*Math.sin(blinkTime/140*Math.PI):1;
      EYES.forEach((e,i)=>{
        const eye=data.eyes[i];
        ctx.save();ctx.translate(e.x,e.y);ctx.scale(1,lid);ctx.drawImage(eye,-eye.width/2,-eye.height/2);ctx.restore();
      });
      wrap.dataset.state=stateKey||'idle';
      if(!reduced)schedule();
    }
    function schedule(){if(!frame&&!dead&&data&&renderer&&!document.hidden&&visible)frame=requestAnimationFrame(render);}
    const observer=new MutationObserver(()=>{stateKey=host.className;stateStart=performance.now();schedule();});observer.observe(host,{attributes:true,attributeFilter:['class']});
    const onVisibility=()=>{if(document.hidden){cancelAnimationFrame(frame);frame=0;}else{last=0;blinkStart=-Infinity;nextBlink=performance.now()+blinkDelay();schedule();}};
    const onMotion=()=>{angles=[0,0,0,0];blinkStart=-Infinity;nextBlink=performance.now()+blinkDelay();schedule();};
    const onLost=e=>{e.preventDefault();cancelAnimationFrame(frame);frame=0;wrap.classList.remove('ready');wrap.classList.add('loading');};
    const onRestored=()=>{renderer=mesh(body,data.body);wrap.classList.add('ready');wrap.classList.remove('loading');schedule();};
    document.addEventListener('visibilitychange',onVisibility);motion.addEventListener('change',onMotion);
    body.addEventListener('webglcontextlost',onLost);body.addEventListener('webglcontextrestored',onRestored);
    const intersection=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)schedule();else{cancelAnimationFrame(frame);frame=0;}});intersection.observe(host);
    const api={destroy(){dead=true;cancelAnimationFrame(frame);observer.disconnect();resize.disconnect();intersection.disconnect();renderer?.destroy();document.removeEventListener('visibilitychange',onVisibility);motion.removeEventListener('change',onMotion);body.removeEventListener('webglcontextlost',onLost);body.removeEventListener('webglcontextrestored',onRestored);wrap.remove();},get ready(){return !!data&&!!renderer;}};
    host._njCharacter=api;
    assets().then(a=>{if(dead)return;data=a;dimensions();renderer=mesh(body,data.body);wrap.classList.remove('loading');wrap.classList.add('ready');schedule();}).catch(error=>{wrap.dataset.error=error.message;console.warn(error);});
    return api;
  }
  window.NJCharacter={mount,src:PACK['reference.webp']};
})();
